-- Speglar det som lades på databasen 2026-09-21 via apply_migration i sex delar:
--   vq_order_code_from_catalogue_part_01  (kategori valve-terminal, backup, schema, familj)
--   vq_order_code_from_catalogue_part_02  (parametrar, värdelista, rensning av regler)
--   vq_order_code_from_catalogue_part_03  (regler 1–20)
--   vq_order_code_from_catalogue_part_04  (regler 21–40)
--   vq_order_code_from_catalogue_part_05  (regler 41–60)
--   vq_order_code_from_catalogue_part_06  (regler 61–86, dokumentkarta, produktraden döpt om)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts vq,
-- scripts/fingerprint-values.py):
--   regler  86   md5 7f19c812e757c0fb7909225f4c66abf7   villkor 77971a91d611e318c32b82bf771944aa
--   värden 104   md5 cbe7aac9167b38c0a658001529475189
--   schema       md5 1578148250f66e61a7f2aff601cef264
-- Verifierat live: /sv/configurator/vq bygger VV5Q11-08C6FU1 (nyckelns exempel sida 366),
-- VV5Q11-08C6FU1-RS (sida 404) och VV5Q11-08C6FU1-D09RS; stoppar D08 för åtta platser
-- och CE-märkning med 200/220 V AC.
--
-- VQ (ventilrampen): beställnyckeln enligt SMC 5 Port Solenoid Valve VQ1000/2000 Series (sida 366, 370 och 404–406).
-- GENERERAD ur src/lib/catalog/vq-manifold.ts -- redigera inte för hand.
--
-- Rättar familjen vq, som hade mallen 'VQ-{size}-{function}-{voltage}-{connection}'
-- med påhittade värden (enkelventilen är redan familjen vq1000). SMC:s rampkod är
-- VV5Q{serie}1-{platser}{port}{kit}{anslutning}{kabel}{SI-enhet}-{tillval…}-{ce},
-- t.ex. VV5Q11-08C6FU1 (nyckelns exempel sida 366), VV5Q11-08C6T0 (sida 385),
-- VV5Q11-08C6SV (sida 397) och VV5Q11-08C6FU1-D09S (sida 406). Tillvalen
-- skrivs alfabetiskt i en grupp. EX510-kitet (utgående) ingår inte.
--
-- Familjen flyttas till kategorin valve-terminal. Produktraden SMC-VQ döps om
-- till SMC-VV5Q11-08C6FU1 och får katalogens data.

begin;


update configurator_families set category_slug = 'valve-terminal', name = 'VQ' where slug = 'vq';


create schema if not exists backup;
create table if not exists backup.vq_before_20260921 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'vq'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'vq'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'vq';

