update configurator_families set
  title = 'Ventilramp VQ1000/2000 basmonterad plug-in (VV5Q11/VV5Q21), kit D-sub/flatkabel/plint/kabel/seriell/rundkontakt, 1–24 platser',
  description = 'SMC VQ1000/2000 base mounted plug-in manifold VV5Q11/VV5Q21 for the VQ1000/2000 plug-in valves (family vq1000): F kit D-sub connector, P kit flat ribbon cable, T kit terminal block box, L kit lead wire, S kit serial transmission EX120/124 (DeviceNet, CC-Link, CompoNet) and M kit circular connector (VQ2000), 1–24 stations depending on kit, cylinder ports ø3.2–ø8 One-touch fittings or M5 (metric or inch, straight or elbow, mixed), options for 200/220 VAC, back pressure check valves, DIN rail, regulator and ejector units (VQ1000), special wiring, name plate, external pilot, built-in silencer and IP65 (VQ2000), CE/UKCA. The EX510 kit (to be discontinued) is not included.',
  stroke_min_mm = null,
  stroke_max_mm = null,
  order_code_template = 'VV5Q{series}1-{stations}{port}{kit}{entry}{cable}{si_unit}-{ac}{check}{din}{regulator}{ejector}{wiring}{nameplate}{ext_pilot}{silencer}{ip65}-{ce}',
  rules_schema_id = 'SCHEMA-VQ-V1'
where slug = 'vq';


