_en":"SV: CC-Link, 16 outputs; the valves have light/surge suppressor and 24 VDC (page 397).","goto_step":"vq-si_unit"},{"severity":"info","if_json":{"==":[{"var":"si_unit"},"ZB"]},"message_sv":"SZB: CompoNet, pluskommun, 16 utgångar; ventilerna har ljus/skyddsdiod och 24 V DC (sida 397).","message_en":"SZB: CompoNet, positive common, 16 outputs; the valves have light/surge suppressor and 24 VDC (page 397).","goto_step":"vq-si_unit"},{"severity":"info","if_json":{"==":[{"var":"si_unit"},"ZBN"]},"message_sv":"SZBN: CompoNet, minuskommun, 16 utgångar; ventilerna har ljus/skyddsdiod och 24 V DC (sida 397).","message_en":"SZBN: CompoNet, negative common, 16 outputs; the valves have light/surge suppressor and 24 VDC (page 397).","goto_step":"vq-si_unit"},{"severity":"info","if_json":{"==":[{"var":"check"},"B"]},"message_sv":"B: Backventil mot mottryck på alla platser; bara vissa platser anges på specifikationsbladet (sida 366, not 2).","message_en":"B: Back pressure check valves on all stations; for certain stations only, specify the positions on the manifold specification sheet (page 366, note 2).","goto_step":"vq-check"},{"severity":"info","if_json":{"==":[{"var":"wiring"},"K"]},"message_sv":"K: Specialkoppling (annat än dubbelkoppling): kopplingen per station anges på specifikationsbladet (sida 366, not 5).","message_en":"K: Special wiring (other than double wiring): the wiring per station is specified on the manifold specification sheet (page 366, note 5).","goto_step":"vq-wiring"},{"severity":"info","if_json":{"==":[{"var":"ext_pilot"},"R"]},"message_sv":"R: Extern pilot: X-porten får snabbkoppling C4 (VQ1000) / C6 (VQ2000); ventilerna beställs med R, t.ex. VQ1100R-51; för vakuum eller matning under 0,1–0,2 MPa (sida 404).","message_en":"R: External pilot: the X port gets a C4 (VQ1000) / C6 (VQ2000) One-touch fitting; order the valves with R, e.g. VQ1100R-51; for vacuum or supply below 0.1–0.2 MPa (page 404).","goto_step":"vq-ext_pilot"},{"severity":"info","if_json":{"==":[{"var":"silencer"},"S"]},"message_sv":"S: Direkt avluftning med inbyggd ljuddämpare; skydda utloppet från vatten om W (IP65) väljs (sida 370, not 7).","message_en":"S: Direct exhaust with built-in silencer; keep the outlet away from water if W (IP65) is selected (page 370, note 7).","goto_step":"vq-silencer"},{"severity":"info","if_json":{"==":[{"var":"ip65"},"W"]},"message_sv":"W: Kapsling IP65 (dammtät, spolsäker) för VQ2000 med T/L/S/M-kit (sida 375, not 4).","message_en":"W: Enclosure IP65 (dust-tight, water-jet-proof) for the VQ2000 with T/L/S/M kit (page 375, note 4).","goto_step":"vq-ip65"},{"severity":"info","if_json":{"==":[{"var":"ac"},"2"]},"message_sv":"2: Rampen kopplad för 200/220 V AC-ventiler (F- och L-kit); CE/UKCA-märkning (Q) finns bara för DC (sida 366).","message_en":"2: The manifold wired for 200/220 VAC valves (F and L kits); CE/UKCA marking (Q) is only available for DC (page 366).","goto_step":"vq-ac"},{"severity":"info","if_json":{"==":[{"var":"nameplate"},"N"]},"message_sv":"N: Namnskylt; beställs separat när blindplatta med kontakt eller ventil med glidlås monteras i efterhand (sida 366, not 9).","message_en":"N: Name plate; ordered separately when a blanking plate with connector or a slide-locking valve is mounted later (page 366, note 9).","goto_step":"vq-nameplate"}]'::jsonb) r;

insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-VQ-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"info","if_json":{"==":[{"var":"ejector"},"J"]},"message_sv":"J: Ejektorenhet på rampen; placeringen anges på specifikationsbladet (sida 418).","message_en":"J: Ejector unit on the manifold; the position is specified on the manifold specification sheet (page 418).","goto_step":"vq-ejector"},{"severity":"info","if_json":{"in":[{"var":"regulator"},["G1","G2","G3"]]},"message_sv":"Regulatorenheter (VQ1000): placeringen anges på specifikationsbladet (sida 366, not 3).","message_en":"Regulator units (VQ1000): the positions are specified on the manifold specification sheet (page 366, note 3).","goto_step":"vq-regulator"},{"severity":"info","if_json":{"in":[{"var":"din"},["D","D0"]]},"message_sv":"DIN-skena: D ger en skena ca 30 mm längre än rampen, D0 bara fästena (VVQ1000-57A/VVQ2000-57A); lös skena beställs som AXT100-DR-□ (sida 406).","message_en":"DIN rail: D gives a rail approx. 30 mm longer than the manifold, D0 only the brackets (VVQ1000-57A/VVQ2000-57A); a separate rail is ordered as AXT100-DR-□ (page 406).","goto_step":"vq-din"},{"severity":"info","if_json":{"in":[{"var":"port"},["CM","LM","MM","NM"]]},"message_sv":"Blandade portar: storlek, pluggar och tillval per station anges på rampens specifikationsblad (sida 366, not 1–2).","message_en":"Mixed ports: sizes, plugs and options per station are specified on the manifold specification sheet (page 366, notes 1–2).","goto_step":"vq-port"},{"severity":"info","if_json":{"==":[{"var":"ce"},"Q"]},"message_sv":"Q: CE/UKCA-märkt utförande, bara med DC-ventiler (sida 366).","message_en":"Q: CE/UKCA-compliant version, DC valves only (page 366).","goto_step":"vq-ce"},{"severity":"error","if_json":{"and":[{"==":[{"var":"ce"},"Q"]},{"==":[{"var":"ac"},"2"]}]},"message_sv":"CE/UKCA-märkning (Q) finns bara för DC — inte med 200/220 V AC (2) (sida 366).","message_en":"CE/UKCA marking (Q) is only available for DC — not with 200/220 VAC (2) (page 366).","goto_step":"vq-ce"}]'::jsonb) r;

insert into knowledge_doc_families (source_file, family_slug, doc_title)
values ('smc-kat-vq1000.pdf', 'vq', 'SMC — SMC 5 Port Solenoid Valve VQ1000/2000 Series')
on conflict (source_file, family_slug) do update set doc_title = excluded.doc_title;


update products set
  sku = 'SMC-VV5Q11-08C6FU1',
  family = 'VQ',
  name = 'VV5Q11-08C6FU1 VQ1000 valve manifold, 8 stations, D-sub connector',
  description = 'SMC VQ1000 base mounted plug-in manifold VV5Q11-08C6FU1: 8 valve stations, cylinder ports ø6 One-touch fittings, P/R ports ø8, F kit D-sub connector (25 pins) with top entry and 1.5 m cable, double wiring, internal pilot, direct mounting. Valves (VQ1100-51 etc., family vq1000) are ordered per station; kits P/T/L/S/M, 1–24 stations and options (back pressure check valve, DIN rail, external pilot, built-in silencer, IP65 on VQ2000) via the configurator. Catalogue pages 366 and 376.',
  category_id = (select id from categories where slug = 'valve-terminal'),
  voltage = '24 VDC'
where sku = 'SMC-VQ';

update product_specs s set value = x.value, unit = x.unit
from products p, (values
  ('function', 'Manifold for 5-port plug-in valves VQ1000 (VQ1100-51 etc.)', null),
  ('operating_pressure', '0.1–0.7', 'MPa'),
  ('series', 'VQ1000', null),
  ('temp_range', '-10…+50', '°C')
) as x(key, value, unit)
where s.product_id = p.id and p.sku = 'SMC-VV5Q11-08C6FU1' and s.key = x.key;

delete from product_specs s using products p
where s.product_id = p.id and p.sku = 'SMC-VV5Q11-08C6FU1' and s.key = 'actuation';

insert into product_specs (product_id, key, value, unit)
select p.id, x.key, x.value, x.unit
from products p
cross join lateral (values
  ('stations', '8 (manifold available with 1–24 depending on kit)', 'stations'),
  ('kit', 'F: D-sub connector 25 pins, top entry, 1.5 m cable', null),
  ('port_size', 'A/B ø6, P/R ø8 One-touch fittings', null),
  ('flow_c', '0.70–0.85 dm³/(s·bar) per valve (2-position single, metal/rubber seal)', null),
  ('max_pressure', '7', 'bar'),
  ('solenoid_voltage', '24 VDC (12 VDC, 100/110/200/220 VAC valves available)', null),
  ('order_code_example', 'VV5Q11-08C6FU1', null),
  ('catalogue', 'SMC VQ1000/2000, How to Order Manifold sida 366 (VQ1000) och 370 (VQ2000), F-kit sida 376, data sida 374–375', null)
) as x(key, value, unit)
where p.sku = 'SMC-VV5Q11-08C6FU1'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


commit;

